import{_ as e,o as i,c as n,a2 as o}from"./chunks/framework.CgxQ0r6v.js";const g=JSON.parse('{"title":"Propuesta de Innovación Curricular: Algorítmica y Programación (2026)","description":"","frontmatter":{},"headers":[],"relativePath":"materias/Algoritmica_y_Programacion/Propuesta_Contenido_Programatico_2026.md","filePath":"materias/Algoritmica_y_Programacion/Propuesta_Contenido_Programatico_2026.md"}'),r={name:"materias/Algoritmica_y_Programacion/Propuesta_Contenido_Programatico_2026.md"};function s(t,a,d,l,c,u){return i(),n("div",null,[...a[0]||(a[0]=[o('<h1 id="propuesta-de-innovacion-curricular-algoritmica-y-programacion-2026" tabindex="-1">Propuesta de Innovación Curricular: Algorítmica y Programación (2026) <a class="header-anchor" href="#propuesta-de-innovacion-curricular-algoritmica-y-programacion-2026" aria-label="Permalink to &quot;Propuesta de Innovación Curricular: Algorítmica y Programación (2026)&quot;">​</a></h1><h3 id="campo-de-investigacion-informatica" tabindex="-1"><strong>Campo de Investigación:</strong> Informática <a class="header-anchor" href="#campo-de-investigacion-informatica" aria-label="Permalink to &quot;**Campo de Investigación:** Informática&quot;">​</a></h3><h3 id="area-de-investigacion-informatica-aplicada" tabindex="-1"><strong>Área de Investigación:</strong> Informática Aplicada <a class="header-anchor" href="#area-de-investigacion-informatica-aplicada" aria-label="Permalink to &quot;**Área de Investigación:** Informática Aplicada&quot;">​</a></h3><h3 id="linea-de-investigacion-principal-ingenieria-del-software" tabindex="-1"><strong>Línea de Investigación Principal:</strong> Ingeniería del Software <a class="header-anchor" href="#linea-de-investigacion-principal-ingenieria-del-software" aria-label="Permalink to &quot;**Línea de Investigación Principal:** Ingeniería del Software&quot;">​</a></h3><h3 id="linea-de-investigacion-secundaria-desarrollo-de-aplicaciones" tabindex="-1"><strong>Línea de Investigación Secundaria:</strong> Desarrollo de Aplicaciones <a class="header-anchor" href="#linea-de-investigacion-secundaria-desarrollo-de-aplicaciones" aria-label="Permalink to &quot;**Línea de Investigación Secundaria:** Desarrollo de Aplicaciones&quot;">​</a></h3><h3 id="enfoque-construccion-del-pensamiento-logico-algoritmico-mediante-un-ecosistema-unificado" tabindex="-1"><strong>Enfoque:</strong> Construcción del Pensamiento Lógico-Algorítmico mediante un Ecosistema Unificado <a class="header-anchor" href="#enfoque-construccion-del-pensamiento-logico-algoritmico-mediante-un-ecosistema-unificado" aria-label="Permalink to &quot;**Enfoque:** Construcción del Pensamiento Lógico-Algorítmico mediante un Ecosistema Unificado&quot;">​</a></h3><h2 id="justificacion-pedagogica-e-investigativa" tabindex="-1">Justificación Pedagógica e Investigativa <a class="header-anchor" href="#justificacion-pedagogica-e-investigativa" aria-label="Permalink to &quot;Justificación Pedagógica e Investigativa&quot;">​</a></h2><h3 id="vinculacion-con-las-lineas-de-investigacion-del-pnfi" tabindex="-1">Vinculación con las Líneas de Investigación del PNFI <a class="header-anchor" href="#vinculacion-con-las-lineas-de-investigacion-del-pnfi" aria-label="Permalink to &quot;Vinculación con las Líneas de Investigación del PNFI&quot;">​</a></h3><p>De acuerdo con la estructura jerárquica de investigación del Programa Nacional de Formación en Informática (PNFI), las líneas de investigación se definen como grupos de proyectos y planes de trabajo organizados de forma sistemática para abordar áreas del conocimiento de manera cooperativa y multidisciplinaria, con el propósito de orientar la investigación científica dentro de los Proyectos Sociotecnológicos (PST) y dar respuestas pertinentes a los problemas de las comunidades.</p><p>La presente propuesta se inscribe de manera principal en la línea de <strong>Ingeniería del Software</strong>, por cuanto su contenido aborda las siguientes dimensiones operativas (programas) de dicha línea:</p><ul><li><strong>Análisis e Ingeniería de Requerimientos:</strong> A través de la Metodología de las 4 Fases (Unidad 4), el estudiante aprende a identificar, analizar, documentar y validar los datos de entrada, procesos y salidas de un problema antes de escribir una sola línea de código. Según el documento de líneas, esta dimensión incluye &quot;técnicas de elicitación, análisis de consistencia, trazabilidad y especificación formal, asegurando que el software responda a las expectativas del usuario&quot;.</li><li><strong>Arquitectura y Diseño de Software:</strong> Las unidades de Programación Modular (Unidad 6), Estructuras de Datos (Unidades 7-9), Punteros (Unidad 11), Listas Enlazadas (Unidad 12), Recursividad (Unidad 13) y Pilas, Colas y Árboles (Unidad 14) forman al estudiante en los principios de modularidad, desacoplamiento y escalabilidad que define esta dimensión.</li><li><strong>Gestión, Calidad y Seguridad del Software:</strong> La Unidad 2 (Estándares de Calidad) introduce al estudiante en las prácticas de documentación y control de calidad desde el primer trimestre. Esta dimensión se orienta a &quot;mejorar la eficiencia del proceso, la confiabilidad del producto y la protección de datos&quot;.</li><li><strong>Ingeniería de Datos y Automatización de Procesos:</strong> La Unidad 10 (Archivos y Persistencia en formato JSON) establece el primer contacto del estudiante con la persistencia de datos. Esta dimensión abarca &quot;diseño y gestión de modelos de datos, persistencia eficiente&quot; y constituye una competencia transversal.</li><li><strong>Interfaces y Experiencia de Usuario (UX/UI):</strong> Si bien en Algorítmica el estudiante trabaja en entorno CLI, los principios de diseño centrado en el usuario y la claridad en la presentación de salidas sientan las bases para la dimensión de UX/UI que se desarrollará plenamente en Programación II.</li></ul><p>De manera secundaria, la propuesta establece un puente hacia la línea de <strong>Desarrollo de Aplicaciones</strong>, específicamente en los siguientes programas:</p><ul><li><strong>Servicios de integración para aplicaciones:</strong> Al utilizar objetos literales (Unidad 9) y el formato JSON para persistencia (Unidad 10), el estudiante adquiere el formato estándar de intercambio de datos (REST, JSON, XML) que posteriormente consumirá y producirá en arquitecturas cliente-servidor durante Programación II.</li><li><strong>Modelado y gestión de datos:</strong> La Unidad 10 (Archivos JSON) y la Unidad 9 (Objetos Literales) introducen el diseño conceptual de estructuras de datos que sustentan el funcionamiento de las aplicaciones, preparando al estudiante para el modelado de bases de datos relacionales en el Trayecto II.</li></ul><h3 id="fundamentacion-pedagogica" tabindex="-1">Fundamentación Pedagógica <a class="header-anchor" href="#fundamentacion-pedagogica" aria-label="Permalink to &quot;Fundamentación Pedagógica&quot;">​</a></h3><p>La presente propuesta surge de un análisis crítico sobre los procesos de enseñanza-aprendizaje en el PNFI, fundamentándose en la necesidad de transitar de una pedagogía de la herramienta hacia una pedagogía del pensamiento analítico. Bajo el Documento Rector del PNFI, esta actualización busca consolidar la Soberanía Cognitiva del estudiante, permitiéndole dominar las estructuras fundamentales de la computación independientemente de las fluctuaciones tecnológicas efímeras.</p><p>La adopción de un ecosistema unificado basado en Node.js y el entorno de interfaz de línea de comandos (CLI) constituye una estrategia didáctica para mitigar la dispersión cognitiva y centrar el esfuerzo intelectual en la resolución de problemas mediante la Metodología de las 4 Fases. Este rigor metodológico asegura la formación de un profesional con alta capacidad de abstracción, requisito indispensable para el desarrollo tecnológico endógeno y la soberanía informática nacional.</p><h2 id="diagnostico-de-obsolescencia-y-desafio-pedagogico" tabindex="-1">Diagnóstico de Obsolescencia y Desafío Pedagógico <a class="header-anchor" href="#diagnostico-de-obsolescencia-y-desafio-pedagogico" aria-label="Permalink to &quot;Diagnóstico de Obsolescencia y Desafío Pedagógico&quot;">​</a></h2><p>Tras un proceso de observación y evaluación de resultados académicos, se identifican las siguientes debilidades estructurales en el contenido programático vigente que esta propuesta busca superar:</p><ul><li><p><strong>Fragmentación Tecnológica:</strong> La enseñanza de lenguajes inconexos genera una interrupción en el flujo de aprendizaje. Al mantener un stack unificado, el estudiante optimiza su energía mental hacia la profundización lógica en lugar de la memorización de múltiples sintaxis.</p></li><li><p><strong>Desarticulación con las Líneas de Investigación:</strong> El contenido anterior no establece una conexión explícita con las dimensiones operativas de las líneas de investigación del PNFI. Esta propuesta vincula cada unidad con los programas de Ingeniería del Software (análisis de requerimientos, arquitectura, calidad), permitiendo que los aprendizajes del Trayecto I tengan continuidad directa en los PST.</p></li><li><p><strong>Brecha con los Estándares de la Industria:</strong> Mantener herramientas y lenguajes aislados de la web moderna dificulta la integración en los Proyectos Socio-Tecnológicos. Esta actualización alinea la formación con los estándares contemporáneos de desarrollo de software, facilitando la aplicabilidad inmediata del conocimiento.</p></li><li><p><strong>Ausencia de Puente Curricular:</strong> El contenido original no preparaba al estudiante para la transición hacia Programación II. Al incorporar JSON y objetos literales como formatos de datos (línea de Desarrollo de Aplicaciones), esta propuesta crea una continuidad orgánica entre trayectos.</p></li></ul><hr><h2 id="trimestre-i-i-fundamentos-y-estructuras-unidades-1-5" tabindex="-1">Trimestre I-I: Fundamentos y Estructuras (Unidades 1-5) <a class="header-anchor" href="#trimestre-i-i-fundamentos-y-estructuras-unidades-1-5" aria-label="Permalink to &quot;Trimestre I-I: Fundamentos y Estructuras (Unidades 1-5)&quot;">​</a></h2><h3 id="unidad-1-algoritmo-y-programas" tabindex="-1">Unidad 1: Algoritmo y Programas <a class="header-anchor" href="#unidad-1-algoritmo-y-programas" aria-label="Permalink to &quot;Unidad 1: Algoritmo y Programas&quot;">​</a></h3><ul><li>Concepto de Algoritmos y Programas.</li><li>Lenguaje algorítmico y de programación.</li><li>Partes, características y elementos para construir un algoritmo.</li><li>Formas de representar un algoritmo: Lenguaje Natural, pseudocódigo y diagrama de flujo (bajo estándar internacional ISO 5807 / ANSI).</li><li>Traza de un algoritmo (corrida en frío / prueba de escritorio).</li></ul><h3 id="unidad-2-estandares-de-calidad-en-el-diseno-de-algoritmos-y-construccion-de-programas" tabindex="-1">Unidad 2: Estándares de Calidad en el Diseño de Algoritmos y Construcción de Programas <a class="header-anchor" href="#unidad-2-estandares-de-calidad-en-el-diseno-de-algoritmos-y-construccion-de-programas" aria-label="Permalink to &quot;Unidad 2: Estándares de Calidad en el Diseño de Algoritmos y Construcción de Programas&quot;">​</a></h3><ul><li>Introducción a los estándares de calidad (legibilidad, mantenibilidad y norma ISO/IEC 25010).</li><li>Formas y técnicas de documentar algoritmos y programas (convenciones de identificadores, comentarios técnicos y código autodocumentado).</li></ul><h3 id="unidad-3-datos-y-entidades-primitivas" tabindex="-1">Unidad 3: Datos y Entidades Primitivas <a class="header-anchor" href="#unidad-3-datos-y-entidades-primitivas" aria-label="Permalink to &quot;Unidad 3: Datos y Entidades Primitivas&quot;">​</a></h3><ul><li>Concepto y diferencia entre dato e información; tipos de datos primitivos, operadores y evaluación de expresiones.</li><li>Identificadores y reglas de escritura (<code>camelCase</code>, <code>UPPER_SNAKE_CASE</code>).</li><li>Variables y constantes (Uso de <code>let</code> y <code>const</code> en Node.js) y clasificación de variables según su contenido (numéricas, lógicas, alfanuméricas) y su uso algorítmico (de trabajo, contador y acumulador).</li></ul><h3 id="unidad-4-metodologia-para-el-analisis-y-planteamiento-de-problemas" tabindex="-1">Unidad 4: Metodología para el Análisis y Planteamiento de Problemas <a class="header-anchor" href="#unidad-4-metodologia-para-el-analisis-y-planteamiento-de-problemas" aria-label="Permalink to &quot;Unidad 4: Metodología para el Análisis y Planteamiento de Problemas&quot;">​</a></h3><ul><li>Identificación del problema, entradas requeridas, procesos de transformación y salidas esperadas.</li><li>Aplicación formal de la Metodología de las 4 Fases (Declaración, Entrada, Cálculo y Salida).</li></ul><h3 id="unidad-5-programacion-estructurada" tabindex="-1">Unidad 5: Programación Estructurada <a class="header-anchor" href="#unidad-5-programacion-estructurada" aria-label="Permalink to &quot;Unidad 5: Programación Estructurada&quot;">​</a></h3><ul><li>Teoremas de la programación estructurada (Teorema de Böhm-Jacopini: secuencia, selección e iteración).</li><li>Estructuras de decisión (Simples, dobles, múltiples, anidadas y selectivas) y Álgebra de Boole.</li><li>Estructuras iterativas (<code>while</code>, <code>do...while</code>, <code>for</code> y bucles anidados).</li></ul><hr><h2 id="trimestre-i-ii-modularidad-y-estructuras-de-datos-unidades-6-10" tabindex="-1">Trimestre I-II: Modularidad y Estructuras de Datos (Unidades 6-10) <a class="header-anchor" href="#trimestre-i-ii-modularidad-y-estructuras-de-datos-unidades-6-10" aria-label="Permalink to &quot;Trimestre I-II: Modularidad y Estructuras de Datos (Unidades 6-10)&quot;">​</a></h2><h3 id="unidad-6-programacion-modular" tabindex="-1">Unidad 6: Programación Modular <a class="header-anchor" href="#unidad-6-programacion-modular" aria-label="Permalink to &quot;Unidad 6: Programación Modular&quot;">​</a></h3><ul><li>Funciones y procedimientos: Definición y Declaración.</li><li>Ámbito de variables: Datos locales y globales (Scope).</li><li>Paso de parámetros y retorno de valores.</li></ul><h3 id="unidad-7-arreglos" tabindex="-1">Unidad 7: Arreglos <a class="header-anchor" href="#unidad-7-arreglos" aria-label="Permalink to &quot;Unidad 7: Arreglos&quot;">​</a></h3><ul><li>Definición, clasificación y operaciones básicas.</li><li>Métodos de Ordenamiento (Burbuja, Inserción).</li><li>Métodos de búsqueda (Secuencial, Binaria).</li></ul><h3 id="unidad-8-tratamiento-de-cadenas-de-caracteres" tabindex="-1">Unidad 8: Tratamiento de Cadenas de Caracteres <a class="header-anchor" href="#unidad-8-tratamiento-de-cadenas-de-caracteres" aria-label="Permalink to &quot;Unidad 8: Tratamiento de Cadenas de Caracteres&quot;">​</a></h3><ul><li>Definición y manipulación de texto mediante funciones nativas.</li></ul><h3 id="unidad-9-estructuras-de-registros" tabindex="-1">Unidad 9: Estructuras de Registros <a class="header-anchor" href="#unidad-9-estructuras-de-registros" aria-label="Permalink to &quot;Unidad 9: Estructuras de Registros&quot;">​</a></h3><ul><li>Definición, declaración y acceso a objetos literales.</li><li>Arreglos de estructuras.</li></ul><h3 id="unidad-10-archivos" tabindex="-1">Unidad 10: Archivos <a class="header-anchor" href="#unidad-10-archivos" aria-label="Permalink to &quot;Unidad 10: Archivos&quot;">​</a></h3><ul><li>Persistencia de datos en disco duro.</li><li>Gestión de archivos mediante el módulo fs (Formato JSON).</li></ul><hr><h2 id="trimestre-i-iii-gestion-de-memoria-y-estructuras-dinamicas-unidades-11-14" tabindex="-1">Trimestre I-III: Gestión de Memoria y Estructuras Dinámicas (Unidades 11-14) <a class="header-anchor" href="#trimestre-i-iii-gestion-de-memoria-y-estructuras-dinamicas-unidades-11-14" aria-label="Permalink to &quot;Trimestre I-III: Gestión de Memoria y Estructuras Dinámicas (Unidades 11-14)&quot;">​</a></h2><h3 id="unidad-11-punteros" tabindex="-1">Unidad 11: Punteros <a class="header-anchor" href="#unidad-11-punteros" aria-label="Permalink to &quot;Unidad 11: Punteros&quot;">​</a></h3><ul><li>Definición, operadores y gestión de referencias en memoria.</li><li>Punteros y estructuras.</li></ul><h3 id="unidad-12-listas-enlazadas" tabindex="-1">Unidad 12: Listas Enlazadas <a class="header-anchor" href="#unidad-12-listas-enlazadas" aria-label="Permalink to &quot;Unidad 12: Listas Enlazadas&quot;">​</a></h3><ul><li>Listas simplemente enlazadas: Inserción, búsqueda y eliminación.</li><li>Introducción a listas doblemente enlazadas y circulares.</li></ul><h3 id="unidad-13-recursividad" tabindex="-1">Unidad 13: Recursividad <a class="header-anchor" href="#unidad-13-recursividad" aria-label="Permalink to &quot;Unidad 13: Recursividad&quot;">​</a></h3><ul><li>Fundamentos, caso base y diseño de algoritmos recursivos.</li></ul><h3 id="unidad-14-introduccion-a-las-estructuras-de-datos-dinamicas-avanzadas-pilas-colas-y-arboles" tabindex="-1">Unidad 14: Introducción a las Estructuras de Datos Dinámicas Avanzadas: Pilas, Colas y Árboles <a class="header-anchor" href="#unidad-14-introduccion-a-las-estructuras-de-datos-dinamicas-avanzadas-pilas-colas-y-arboles" aria-label="Permalink to &quot;Unidad 14: Introducción a las Estructuras de Datos Dinámicas Avanzadas: Pilas, Colas y Árboles&quot;">​</a></h3><ul><li>Definición, funcionalidades e implementación básica de Stacks, Queues y Árboles Binarios.</li></ul><hr><h2 id="estrategias-pedagogicas" tabindex="-1">Estrategias Pedagógicas <a class="header-anchor" href="#estrategias-pedagogicas" aria-label="Permalink to &quot;Estrategias Pedagógicas&quot;">​</a></h2><p>Las estrategias seleccionadas responden a los principios del &quot;aprender haciendo&quot; promovidos por el Documento Rector del PNFI y se articulan con la dimensión de Gestión y Calidad de la línea de Ingeniería del Software:</p><ul><li><strong>Metodología de las 4 Fases:</strong> Aplicación obligatoria en cada resolución de problemas (Analizar, Diseñar, Codificar, Probar). Esta metodología se alinea directamente con la dimensión de Análisis e Ingeniería de Requerimientos.</li><li><strong>Miniproyecto Formativo Incremental:</strong> En concordancia directa con las estrategias oficiales del Documento Rector para la unidad curricular APT1312, los estudiantes planifican y desarrollan un miniproyecto transversal por equipos a medida que adquieren los saberes de cada trimestre (evolucionando desde estructuras en memoria hasta persistencia en archivos JSON).</li><li><strong>Clase Invertida (Flipped Classroom):</strong> Apropiación teórica previa mediante guías en Markdown y taller práctico presencial, fomentando la autonomía del aprendizaje en las Horas de Trabajo de Estudio Independiente (HTEI).</li><li><strong>Programación Dirigida (Live Coding):</strong> Demostración de lógica, trazas en frío y depuración en tiempo real por parte del docente, simulando entornos profesionales de desarrollo.</li><li><strong>Documentación como Hábito:</strong> Desde la Unidad 2, el estudiante documenta cada solución siguiendo estándares de calidad y diagramación ISO 5807, creando una cultura de la documentación alineada con las prácticas de la Ingeniería del Software.</li></ul><h2 id="recursos-tecnologicos" tabindex="-1">Recursos Tecnológicos <a class="header-anchor" href="#recursos-tecnologicos" aria-label="Permalink to &quot;Recursos Tecnológicos&quot;">​</a></h2><p>El ecosistema tecnológico se seleccionó para garantizar la continuidad curricular con Programación II y la alineación con la línea de Desarrollo de Aplicaciones:</p><ul><li><strong>Lenguaje:</strong> JavaScript (Node.js runtime) — permite la transición directa hacia el desarrollo web en trayectos posteriores.</li><li><strong>Herramientas de Desarrollo:</strong> Visual Studio Code, Terminal de comandos (CLI), Librería prompt-sync.</li><li><strong>Control de Versiones:</strong> Git y GitHub para la gestión del código fuente, alineado con las prácticas de Ingeniería del Software.</li><li><strong>Formato de Datos:</strong> JSON como formato estándar de persistencia (Unidad 10), creando el puente hacia servicios REST en Programación II.</li><li><strong>Documentación:</strong> Guías en Markdown y repositorios de control de versiones.</li></ul><h2 id="sistema-de-evaluacion" tabindex="-1">Sistema de Evaluación <a class="header-anchor" href="#sistema-de-evaluacion" aria-label="Permalink to &quot;Sistema de Evaluación&quot;">​</a></h2><p>La evaluación formativa y sumativa se orienta a validar las competencias asociadas a las dimensiones operativas de la línea de Ingeniería del Software:</p><ul><li><strong>Pruebas de Lógica y Corridas en Frío (50%):</strong> Resolución de algoritmos, diagramas de flujo y trazas en papel/pizarra para validar el pensamiento analítico. Evalúa la capacidad de Análisis e Ingeniería de Requerimientos.</li><li><strong>Laboratorios de Implementación (25%):</strong> Traducción de lógica a programas funcionales en Node.js. Evalúa competencias de Arquitectura y Diseño de Software.</li><li><strong>Retos de Algoritmia Avanzada y Miniproyecto (25%):</strong> Resolución de problemas de alta complejidad en tiempo real e integración progresiva de estructuras de datos en casos prácticos.</li></ul><h2 id="referencias-bibliograficas" tabindex="-1">Referencias Bibliográficas <a class="header-anchor" href="#referencias-bibliograficas" aria-label="Permalink to &quot;Referencias Bibliográficas&quot;">​</a></h2><ul><li>Haverbeke, M. (2018). <em>Eloquent JavaScript: A Modern Introduction to Programming</em>. <a href="https://eloquentjavascript.net/" target="_blank" rel="noreferrer">https://eloquentjavascript.net/</a></li><li>Simpson, K. (2015). <em>You Don&#39;t Know JS: Up &amp; Going</em>. <a href="https://github.com/getify/You-Dont-Know-JS" target="_blank" rel="noreferrer">https://github.com/getify/You-Dont-Know-JS</a></li><li>Wirth, N. (1987). <em>Algoritmos + Estructuras de Datos = Programas</em>. Ediciones del Castillo.</li><li>Ministerio del Poder Popular para la Educación Universitaria. <em>Documento Rector del PNFI</em>. Caracas, Venezuela.</li><li>Ministerio del Poder Popular para la Educación Universitaria. <em>Líneas de Investigación del PNFI: Actualización 2024</em>. Caracas, Venezuela.</li><li>Mozilla Developer Network (MDN). <em>JavaScript Reference and Web APIs</em>. <a href="https://developer.mozilla.org/es/docs/Web/JavaScript" target="_blank" rel="noreferrer">https://developer.mozilla.org/es/docs/Web/JavaScript</a></li><li>Node.js Foundation. <em>Official Node.js Documentation and Best Practices</em>. <a href="https://nodejs.org/docs/latest/api/" target="_blank" rel="noreferrer">https://nodejs.org/docs/latest/api/</a></li><li>ISO/IEC 25010:2011. <em>Systems and software engineering — Systems and software Quality Requirements and Evaluation (SQuaRE)</em>.</li></ul>',65)])])}const p=e(r,[["render",s]]);export{g as __pageData,p as default};
